// Custom Opening Range + STDV — OpenScript port of "Custom_Opening_Range_STDV.pine" (©GRCtrader)
//
// CONVERSION NOTES — every place this differs from the Pine, and why.
// Full reasoning: docs/openscript-custom-or-stdv-migration-design.md
//
// 1. TIME UNITS. `time` (context series) is epoch MILLISECONDS; the value returned by
//    request.security(..., time) is epoch SECONDS, because the HTF resampler aggregates
//    the dataset's own time column. Mixing them is a silent 1000x error with no
//    diagnostic. The conversion happens ONCE, below, in `orbSec`.
// 2. LEFT EDGE. Levels start where the ORB candle CLOSES, not at its open. `offset` must
//    be a compile-time constant and the value needed here (orbMinutes / chartMinutes) is
//    runtime-dependent. Prices match TradingView; the left edge is one ORB candle later.
// 3. SESSION COUNT is a constant (max_kept), not the Pine's 1-20 input: declarative
//    retention cannot vary at runtime the way imperative line.delete can.
// 4. LINE STYLE is fixed dotted for the STDV levels — `style=` needs a line.style_* enum
//    resolved at compile time, so the Pine's solid/dotted/dashed dropdown cannot drive it.
// 5. LABELS have no "09:30 " prefix — that needs str.tostring, which v1 does not ship.
// 6. ORB TIMEFRAME IS REQUIRED. The Pine falls back to timeframe.period (a STRING) when
//    empty; v1 has no string-valued timeframe expression.
// 7. NO "Futures Timezone Offset" INPUT and no COMEX auto-detect. Both are DEAD in the
//    Pine: `effectiveOffset` is assigned and never read, and the clock uses a hardcoded
//    "Asia/Kolkata" regardless. Porting them would ship controls that do nothing.
// 8. SESSION-BOUNDED LINES, and this one is a DELIBERATE improvement on the Pine.
//    The Pine draws every retained session's lines to last_bar_time, so showing more
//    than one session stacks them into an overlapping band (its own sessionLimit
//    defaults to 1, which hides the problem). Using extend.until +
//    terminate.new_session instead, a PAST session's lines close at the end of the
//    session that spawned them while the LIVE session, having no successor, still
//    rides the live edge. That is one output giving both behaviours, and it is what
//    makes max_kept=5 readable rather than clumsy.
// 9. NO label-visibility toggles. The Pine's showLabels/showSTDVLabels gate only the
//    label; `label=` is const so no input can gate it, and gating the spawn condition
//    would hide the lines too. Labels are always on for the latest session.
//
// The IST offset below is hardcoded to match the Pine's "Asia/Kolkata". Correct for
// NSE/MCX; WRONG for any instrument on another calendar.

indicator("Custom OR + STDV", shorttitle="Custom OR + STDV", overlay=true)

startHour   = input.int(9, "Opening Range Hour (0-23)", minval=0, maxval=23, group="Opening Range Start Time")
startMinute = input.int(15, "Opening Range Minute (0-59)", minval=0, maxval=59, group="Opening Range Start Time")
orbTf       = input.timeframe("15", "ORB Timeframe", group="Settings", tooltip="Timeframe of the opening-range candle. Required — see conversion note 6.")

showOR  = input.bool(true, "Show Opening Range", group="Opening Range")
orColor = input.color(#606470, "OR Color", group="Opening Range")
orWidth = input.int(2, "OR Line Width", group="Styling")
showCE  = input.bool(true, "Show Center Encroachment (C.E.)", group="Opening Range")
ceColor = input.color(#606470, "C.E. Color", group="Opening Range")
ceWidth = input.int(1, "C.E. Line Width", group="Styling")

showSTDV  = input.bool(true, "Show STDV Lines", group="Standard Deviations")
stdvColor = input.color(#606470, "STDV Color", group="Standard Deviations")
stdvWidth = input.int(1, "STDV Line Width", group="Standard Deviations")
showExtSTDV = input.bool(false, "Show Extended 3.0 – 4.5 STDV", group="Standard Deviations")

[orbHigh, orbLow, orbTime] = request.security(syminfo.tickerid, orbTf, [high[1], low[1], time[1]])

// SECONDS (conversion note 1). 19800 = +05:30 IST, matching the Pine's "Asia/Kolkata".
orbSec   = orbTime + 19800
secOfDay = orbSec % 86400
srcHour  = math.floor(secOfDay / 3600)
srcMin   = math.floor((secOfDay % 3600) / 60)

// EDGE-TRIGGERED, and the clause is load-bearing. The last-closed bucket STAYS the
// 09:15 bucket for every chart bar until the next one closes, so the hour/minute test
// alone is a LEVEL condition that spawns orbTf/chartTf duplicate objects per session
// (measured: 3 at bars 6,7,8 for a 15m ORB over 5m bars). `orbTime` changes exactly
// once per bucket, so comparing it with its own previous chart bar is the natural edge.
isORBar = srcHour == startHour and srcMin == startMinute and orbTime != orbTime[1]

ce = (orbHigh + orbLow) / 2
orRange = orbHigh - orbLow

plotlevel(isORBar and showOR, orbHigh, "OR High", color=orColor, width=orWidth, style=line.style_solid, extend=extend.until, terminate=terminate.new_session, max_kept=5, label="OR High {price}", label_latest_only=true)
plotlevel(isORBar and showOR, orbLow, "OR Low", color=orColor, width=orWidth, style=line.style_solid, extend=extend.until, terminate=terminate.new_session, max_kept=5, label="OR Low {price}", label_latest_only=true)
plotlevel(isORBar and showCE, ce, "OR C.E.", color=ceColor, width=ceWidth, style=line.style_dashed, extend=extend.until, terminate=terminate.new_session, max_kept=5, label="OR C.E. {price}", label_latest_only=true)

plotlevel(isORBar and showSTDV, orbHigh + orRange * 0.5, "+0.5 STDV", color=stdvColor, width=stdvWidth, style=line.style_dotted, extend=extend.until, terminate=terminate.new_session, max_kept=5, label="+0.5 STDV {price}", label_latest_only=true)
plotlevel(isORBar and showSTDV, orbLow - orRange * 0.5, "-0.5 STDV", color=stdvColor, width=stdvWidth, style=line.style_dotted, extend=extend.until, terminate=terminate.new_session, max_kept=5, label="-0.5 STDV {price}", label_latest_only=true)
plotlevel(isORBar and showSTDV, orbHigh + orRange * 1.0, "+1.0 STDV", color=stdvColor, width=stdvWidth, style=line.style_dotted, extend=extend.until, terminate=terminate.new_session, max_kept=5, label="+1.0 STDV {price}", label_latest_only=true)
plotlevel(isORBar and showSTDV, orbLow - orRange * 1.0, "-1.0 STDV", color=stdvColor, width=stdvWidth, style=line.style_dotted, extend=extend.until, terminate=terminate.new_session, max_kept=5, label="-1.0 STDV {price}", label_latest_only=true)
plotlevel(isORBar and showSTDV, orbHigh + orRange * 1.5, "+1.5 STDV", color=stdvColor, width=stdvWidth, style=line.style_dotted, extend=extend.until, terminate=terminate.new_session, max_kept=5, label="+1.5 STDV {price}", label_latest_only=true)
plotlevel(isORBar and showSTDV, orbLow - orRange * 1.5, "-1.5 STDV", color=stdvColor, width=stdvWidth, style=line.style_dotted, extend=extend.until, terminate=terminate.new_session, max_kept=5, label="-1.5 STDV {price}", label_latest_only=true)
plotlevel(isORBar and showSTDV, orbHigh + orRange * 2.0, "+2.0 STDV", color=stdvColor, width=stdvWidth, style=line.style_dotted, extend=extend.until, terminate=terminate.new_session, max_kept=5, label="+2.0 STDV {price}", label_latest_only=true)
plotlevel(isORBar and showSTDV, orbLow - orRange * 2.0, "-2.0 STDV", color=stdvColor, width=stdvWidth, style=line.style_dotted, extend=extend.until, terminate=terminate.new_session, max_kept=5, label="-2.0 STDV {price}", label_latest_only=true)
plotlevel(isORBar and showSTDV, orbHigh + orRange * 2.5, "+2.5 STDV", color=stdvColor, width=stdvWidth, style=line.style_dotted, extend=extend.until, terminate=terminate.new_session, max_kept=5, label="+2.5 STDV {price}", label_latest_only=true)
plotlevel(isORBar and showSTDV, orbLow - orRange * 2.5, "-2.5 STDV", color=stdvColor, width=stdvWidth, style=line.style_dotted, extend=extend.until, terminate=terminate.new_session, max_kept=5, label="-2.5 STDV {price}", label_latest_only=true)

plotlevel(isORBar and showSTDV and showExtSTDV, orbHigh + orRange * 3.0, "+3.0 STDV", color=stdvColor, width=stdvWidth, style=line.style_dotted, extend=extend.until, terminate=terminate.new_session, max_kept=5, label="+3.0 STDV {price}", label_latest_only=true)
plotlevel(isORBar and showSTDV and showExtSTDV, orbLow - orRange * 3.0, "-3.0 STDV", color=stdvColor, width=stdvWidth, style=line.style_dotted, extend=extend.until, terminate=terminate.new_session, max_kept=5, label="-3.0 STDV {price}", label_latest_only=true)
plotlevel(isORBar and showSTDV and showExtSTDV, orbHigh + orRange * 3.5, "+3.5 STDV", color=stdvColor, width=stdvWidth, style=line.style_dotted, extend=extend.until, terminate=terminate.new_session, max_kept=5, label="+3.5 STDV {price}", label_latest_only=true)
plotlevel(isORBar and showSTDV and showExtSTDV, orbLow - orRange * 3.5, "-3.5 STDV", color=stdvColor, width=stdvWidth, style=line.style_dotted, extend=extend.until, terminate=terminate.new_session, max_kept=5, label="-3.5 STDV {price}", label_latest_only=true)
plotlevel(isORBar and showSTDV and showExtSTDV, orbHigh + orRange * 4.0, "+4.0 STDV", color=stdvColor, width=stdvWidth, style=line.style_dotted, extend=extend.until, terminate=terminate.new_session, max_kept=5, label="+4.0 STDV {price}", label_latest_only=true)
plotlevel(isORBar and showSTDV and showExtSTDV, orbLow - orRange * 4.0, "-4.0 STDV", color=stdvColor, width=stdvWidth, style=line.style_dotted, extend=extend.until, terminate=terminate.new_session, max_kept=5, label="-4.0 STDV {price}", label_latest_only=true)
plotlevel(isORBar and showSTDV and showExtSTDV, orbHigh + orRange * 4.5, "+4.5 STDV", color=stdvColor, width=stdvWidth, style=line.style_dotted, extend=extend.until, terminate=terminate.new_session, max_kept=5, label="+4.5 STDV {price}", label_latest_only=true)
plotlevel(isORBar and showSTDV and showExtSTDV, orbLow - orRange * 4.5, "-4.5 STDV", color=stdvColor, width=stdvWidth, style=line.style_dotted, extend=extend.until, terminate=terminate.new_session, max_kept=5, label="-4.5 STDV {price}", label_latest_only=true)
